private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int remaining = bb.remaining();
    int bufPos = i;
    while (remaining > 0) {
        if (bufPos >= remaining) {
            break;
        }
        int b = bb.get() & 0xFF;
        if ((b & 0x80) == 0) {
            sb.append((char) b);
        } else {
            int n = readMultibyte(bb, b);
            if (n == -1) {
                throw new IllegalArgumentException("Invalid multibyte prefix");
            }
            for (int j = 0; j < n; j++) {
                b = bb.get() & 0xFF;
                if ((b & 0x80) == 0) {
                    sb.append((char) b);
                } else {
                    throw new IllegalArgumentException("Invalid multibyte sequence");
                }
            }
        }
        bufPos++;
        remaining--;
    }
    return bufPos;
}

private static int readMultibyte(ByteBuffer bb, int b) {
    if (b >= 0xC0 && b <= 0xDF) {
        return 1;
    } else if (b >= 0xE0 && b <= 0xEF) {
        return 2;
    } else if (b >= 0xF0 && b <= 0xF7) {
        return 3;
    } else if (b >= 0xF8 && b <= 0xFB) {
        return 4;
    } else if (b >= 0xFC && b <= 0xFD) {
        return 5;
    } else {
        throw new IllegalArgumentException("Invalid multibyte prefix");
    }
}

