private void enlarge(final int size) {
    // Check if the additional size exceeds the current capacity of the vector
    if (size > (capacity - readPosition)) {
        // Calculate the new capacity required
        int newCapacity = capacity + size;
        // Create a new underlying array with the new capacity
        T[] newArray = (T[]) new Object[newCapacity];
        // Copy the contents of the current array to the new array
        System.arraycopy(array, readPosition, newArray, 0, capacity - readPosition);
        // Set the new array as the underlying array
        array = newArray;
        // Update the current capacity
        capacity = newCapacity;
    }
}

