private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Perform a right rotation on the given node
    TreeNode<T> parent = node.getParent();
    if (parent == null) {
        // If the node is the root, there is nothing to rotate
        return null;
    }
    TreeNode<T> grandparent = parent.getParent();
    if (grandparent == null) {
        // If the node is a root node, there is nothing to rotate
        return null;
    }
    // Find the left child of the grandparent
    TreeNode<T> leftChild = null;
    for (TreeNode<T> child : grandparent.getChildren()) {
        if (child.getData() == node.getData()) {
            leftChild = child;
            break;
        }
    }
    if (leftChild == null) {
        // If the node has no left child, there is nothing to rotate
        return null;
    }
    // Rotate the node to the right by swapping it with its left child
    parent.setRightChild(leftChild);
    grandparent.setLeftChild(node);
    return parent;
}

