@Override
public void write(byte[] b) throws IOException {
    if (b == null || b.length == 0) {
        return;
    }

    int totalBytesWritten = 0;
    int bytesWritten = 0;

    try {
        while (totalBytesWritten < b.length) {
            bytesWritten = write(b, totalBytesWritten, Math.min(bufferSize, b.length - totalBytesWritten));
            totalBytesWritten += bytesWritten;
        }
    } catch (IOException e) {
        throw new IOException("Error writing bytes to the stream", e);
    }
}

public void write(byte b) throws IOException {
    ByteBuffer buffer = ByteBuffer.allocate(1);
    buffer.put(b);
    write(buffer.array());
}

public void write(byte[] b, int off, int len) throws IOException {
    if (closed) {
        throw new IOException("Stream is closed");
    }

    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("The offset or length is outside the bounds of the byte array");
    }

    int totalBytesWritten = 0;
    int bytesWritten = 0;

    try {
        while (totalBytesWritten < len) {
            bytesWritten = write(b, off + totalBytesWritten, Math.min(bufferSize, len - totalBytesWritten));
            totalBytesWritten += bytesWritten;
        }
    } catch (IOException e) {
        throw new IOException("Error writing bytes to the stream", e);
    }
}

