public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
	// get the first node in the buffer
	LinkedBuffer currentNode = node;
	int size = 0;

	// loop through the the buffer and write each node to the output stream
	while (currentNode != null) {
		out.write(currentNode.getData());
		size += currentNode.getSize();
		currentNode = currentNode.getNext();
	}

	// return the total size of the buffer
	return size;
}

