public void readFrom(InputStream in) throws IOException {
        if (in == null) {
            throw new IllegalArgumentException("Input stream cannot be null");
        }
        if (!in.markSupported()) {
            throw new UnsupportedOperationException("Input stream does not support mark");
        }
        in.mark(0);
        int read = 0;
        int size = buffer.length;
        while (read < size) {
            int n = in.read(buffer, readPointer, size - read);
            if (n == -1) {
                break;
            }
            read += n;
            readPointer += n;
        }
        if (read < size) {
            throw new IOException("Could not read enough bytes from input stream");
        }
        readPointer = 0;
    }

@Override public void write(final byte[] b) throws IOException {
    if (b == null) {
        throw new NullPointerException("Buffer is null");
    }

    int len = b.length;
    int offset = 0;
    int count = 0;

    while (len > 0) {
        count = write(b, offset, Math.min(len, (int) Math.min(len, Integer.MAX_VALUE)));
        offset += count;
        len -= count;
    }
}

@Override
public String toJson(JSONWriter.Feature... features) {
    // Step 1: Validate input parameters
    if (features == null || features.length == 0) {
        throw new IllegalArgumentException("No features specified for serialization");
    }
    for (JSONWriter.Feature feature : features) {
        if (feature == null) {
            throw new IllegalArgumentException("Null feature found in the list of serialization features");
        }
    }

    // Step 2: Create a new JSON string builder
    StringBuilder json = new StringBuilder("{");

    // Step 3: Iterate over the features and serialize each one
    for (int i = 0; i < features.length; i++) {
        JSONWriter.Feature feature = features[i];
        json.append("\"").append(feature.getName()).append("\":");
        json.append(feature.getValue().toString());
        if (i < features.length - 1) {
            json.append(",");
        }
    }

    // Step 4: Close the JSON object and return the resulting string
    json.append("}");
    return json.toString();
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null || value == null) {
        return null;
    }
    if (type.isAssignableFrom(value.getClass())) {
        return value;
    }
    if (type == Character.class && value instanceof Number) {
        Number number = (Number) value;
        return Character.valueOf((char) number.intValue());
    }
    if (type == Number.class && value instanceof Character) {
        Character character = (Character) value;
        return number.intValue(character);
    }
    return null;
}

