public static int nextPrime(int desiredCapacity) {
  if (desiredCapacity < 2) {
    return 2;
  }

  int capacity = (int) (desiredCapacity / 1.1 + 1);

  while (!isPrime(capacity)) {
    capacity++;
  }

  return capacity;
}

private static boolean isPrime(int num) {
  if (num < 2) {
    return false;
  }

  for (int i = 2; i <= Math.sqrt(num); i++) {
    if (num % i == 0) {
      return false;
    }
  }

  return true;
}

