public static String unescapeJava(String str) throws Exception {
  if (str == null) {
    return null;
  }
  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < str.length(); i++) {
    char c = str.charAt(i);
    if (c == '\\') {
      if (i + 1 < str.length()) {
        char c2 = str.charAt(i + 1);
        if (c2 == 'n') {
          sb.append('\n');
        } else if (c2 == 'r') {
          sb.append('\r');
        } else if (c2 == 't') {
          sb.append('\t');
        } else if (c2 == 'b') {
          sb.append('\b');
        } else if (c2 == 'f') {
          sb.append('\f');
        } else if (c2 == '\'') {
          sb.append('\'');
        } else if (c2 == '"') {
          sb.append('"');
        } else if (c2 == '\\') {
          sb.append('\\');
        } else {
          throw new Exception("Illegal escape sequence '\\" + c2 + "'");
        }
        i++;
      } else {
        throw new Exception("Illegal escape sequence '\\' at end of string");
      }
    } else {
      sb.append(c);
    }
  }
  return sb.toString();
}

