final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check if the constant pool entry is a CONSTANT_Utf8
    int descriptorIndex = classFileBuffer.getU2(classFileOffset + 8);
    int descriptorType = classFileBuffer.getU1(descriptorIndex);
    if (descriptorType != CONSTANT_Utf8) {
        throw new IllegalArgumentException("Invalid constant pool entry type");
    }

    // Read the string length and string data
    int stringLength = classFileBuffer.getU2(descriptorIndex + 2);
    for (int i = 0; i < stringLength; i++) {
        charBuffer[i] = (char) classFileBuffer.getU1(descriptorIndex + 4 + i);
    }

    return new String(charBuffer, 0, stringLength);
}

private static char decodeHexNibble(final char c) {
    if (c >= '0' && c <= '9') {
        return (char) (c - '0');
    } else if (c >= 'a' && c <= 'f') {
        return (char) (c - 'a' + 10);
    } else if (c >= 'A' && c <= 'F') {
        return (char) (c - 'A' + 10);
    } else {
        return Character.MAX_VALUE;
    }
}

