public static long factorial(int n) {
    if(n < 0) {
       throw new IllegalArgumentException("n must be non-negative.");
    }
    if(n == 0) {
       return 1;
    }
    int result = n;
    for (int i = n - 1; i > 1; i--) {
       result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    // Initialize a circulator to the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Iterate through the outer face nodes
    while (!circ.isAt(stop)) {
        // If the current node satisfies the predicate, return a circulator to it
        if (predicate.test(circ.getNode())) {
            return circ;
        }

        // Move to the next node in the outer face
        circ.moveRight(dir);
    }

    // If we reached the stop node without finding a satisfying node, return a circulator to the stop node
    return circ;
}

