public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        if (byteOffset < 0 || byteOffset > byteLength) {
            throw new IndexOutOfBoundsException("Invalid byte offset: " + byteOffset);
        }
        if (byteLength < 0) {
            throw new IllegalArgumentException("Invalid byte length: " + byteLength);
        }
        if (this.length + byteLength > this.data.length) {
            this.grow(this.length + byteLength);
        }
        for (int i = 0; i < byteLength; i++) {
            this.data[this.length++] = 0;
        }
        return this;
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid byte offset: " + byteOffset);
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("Invalid byte length: " + byteLength);
    }
    if (this.length + byteLength > this.data.length) {
        this.grow(this.length + byteLength);
    }
    System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
    this.length += byteLength;
    return this;
}

