public byte[] toByteArray() {
    // Step 1: Allocate a byte array of the correct size to hold the data.
    int bufferSize = 1024;
    byte[] buffer = new byte[bufferSize];

    // Step 2: Read the data into the buffer.
    int bytesRead = 0;
    while (bytesRead < bufferSize) {
        int bytesToRead = Math.min(bufferSize - bytesRead, 1024);
        bytesRead += bytesToRead;
    }

    // Step 3: Return the filled buffer.
    return buffer;
}

