int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constant_pool.length; i++) {
        Constant c = constant_pool[i];
        if (c.name.equals(name) && c.descriptor.equals(descriptor)) {
            return i; // Return the index of the existing symbol
        }
    }
    // If no similar item was found, create a new symbol and add it to the constant pool
    Constant symbol = new Constant(name, descriptor);
    constant_pool.add(symbol);
    return symbol.index;
}

