private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Step 1: Initialize new label values
    int newLabel;

    // Step 2: Find the bucket with the minimum label
    int minBucketIdx = getBucketIdx(minLabel, bucketsByLabel);

    // Step 3: Move all vertices from the minimum bucket to bucket 0
    Set<Integer> minBucket = bucketsByLabel.get(minBucketIdx);
    newLabel = minLabel - 1;
    for (int vertex : minBucket) {
        labels.set(vertex, newLabel);
    }

    // Step 4: Clear the minimum bucket
    bucketsByLabel.set(minBucketIdx, new HashSet<>());

    // Step 5: Update the labeling of the other buckets
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        Set<Integer> bucket = bucketsByLabel.get(i);
        newLabel = -1;
        if (i == minBucketIdx) {
            continue;
        }
        for (int vertex : bucket) {
            int label = labels.get(vertex);
            if (label == minLabel) {
                labels.set(vertex, newLabel);
            }
        }
    }
}

private int getBucketIdx(int label, List<Set<Integer>> bucketsByLabel) {
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (bucketsByLabel.get(i).contains(label)) {
            return i;
        }
    }
    return -1;
}

