public int readTag() throws IOException {
  // Check if the stream is at EOF
  if (isAtEndOfStream()) {
    return 0;
  }

  // Read the next byte from the stream
  int b = readByteFromStream();

  // If the byte is a valid tag, return it
  if (b >= 0 && b <= 5) {
    return b;
  }

  // If the byte is not a valid tag, throw an IOException
  throw new IOException("Invalid tag: " + b);
}

