public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Step 1: Check if file exists and is readable
    if (!file.exists() || !file.canRead()) {
        throw new FileNotFoundException("File does not exist or is not readable: " + file.getAbsolutePath());
    }
    // Step 2: Check if time ranges are valid
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges cannot be null or empty");
    }
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange.getStartTime() > timeRange.getEndTime()) {
            throw new IllegalArgumentException("Invalid time range: start time cannot be after end time");
        }
    }
    // Step 3: Read the file and parse the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Check if the line is a thread snapshot
            if (line.startsWith("THREAD SNAPSHOT")) {
                // Parse the line and create a ThreadSnapshot object
                String[] parts = line.split("\\t");
                if (parts.length < 4) {
                    throw new IOException("Invalid thread snapshot format: " + line);
                }
                ThreadSnapshot snapshot = new ThreadSnapshot(parts[1], parts[2], parts[3], parts[4]);
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (snapshot.getTimeStamp() >= timeRange.getStartTime() && snapshot.getTimeStamp() <= timeRange.getEndTime()) {
                        threadSnapshots.add(snapshot);
                        break;
                    }
                }
            }
        }
    } catch (IOException e) {
        throw new IOException("Error parsing thread snapshot file", e);
    }
    // Return the list of thread snapshots
    return threadSnapshots;
}
